var BANK=[
{q:'选择正确的冠词：___ sun is shining.',options:['A','An','The'],ans:2,why:'太阳独一无二，用 The。'},
{q:'He ___ to school every day.',options:['go','goes','going'],ans:1,why:'第三人称单数现在时用 goes。'},
{q:'There ___ some books on the desk.',options:['is','are','be'],ans:1,why:'books 复数用 are。'},
{q:'She is ___ honest girl.',options:['a','an','the'],ans:1,why:'honest 以元音音素开头用 an。'},
{q:'I have two ___ .',options:['child','childs','children'],ans:2,why:'child 复数 children。'},
{q:'They ___ playing football now.',options:['is','are','am'],ans:1,why:'they 复数用 are。'},
{q:'This is ___ book I bought.',options:['a','an','the'],ans:2,why:'特指用 the。'},
{q:'She can ___ swim.',options:['to','/','for'],ans:1,why:'情态动词后接动词原形。'},
{q:'He has ___ finished his homework.',options:['yet','already','still'],ans:1,why:'肯定句用 already。'},
{q:'The movie was ___ interesting.',options:['real','really','reality'],ans:1,why:'修饰形容词用副词 really。'},
{q:'We ___ TV when she called.',options:['watched','were watching','watch'],ans:1,why:'过去进行时。'},
{q:'How ___ sugar do you want?',options:['much','many','more'],ans:0,why:'sugar 不可数用 much。'},
{q:'If it rains, we ___ stay home.',options:['will','would','are'],ans:0,why:'真实条件句主句用 will。'},
{q:'He is taller ___ his brother.',options:['then','than','that'],ans:1,why:'比较级用 than。'},
{q:'I ___ a letter yesterday.',options:['write','wrote','written'],ans:1,why:'yesterday 用过去式。'}];
function range(n){var a=[];for(var i=0;i<n;i++)a.push(i);return a;}
function shuffle(a,rng){a=a.slice();for(var i=a.length-1;i>0;i--){var j=Math.floor(rng()*(i+1));var t=a[i];a[i]=a[j];a[j]=t;}return a;}
function getSet(rng,n){var idx=shuffle(range(BANK.length),rng).slice(0,Math.min(n,BANK.length));return idx.map(function(i){return BANK[i];});}
function grade(set,answers){var c=0;for(var i=0;i<set.length;i++){if(answers[i]===set[i].ans)c++;}return {correct:c,total:set.length,pct:Math.round(c/set.length*100)};}
var EXPORTS={BANK:BANK,getSet:getSet,grade:grade};


function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.GrammarForgePure = EXPORTS; }
